CREATE FUNCTION forge.create_vnext_mission_v1(p_mission_id uuid,p_execution_id uuid,p_task_id uuid,p_owner_user_id uuid,p_desired_outcome_digest text,p_constraints_digest text,p_compatibility_pins jsonb,p_workflow_revision text,p_resource_bindings jsonb,p_reason_code text) RETURNS TABLE(mission_id uuid,execution_id uuid,occurred_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_now timestamptz:=clock_timestamp(); v_policy text;
BEGIN
 IF session_user<>'forge' THEN RAISE EXCEPTION 'VNext mission creation requires Forge application login' USING ERRCODE='42501'; END IF; v_policy:=p_compatibility_pins->>'policyRevision';
 IF p_mission_id IS NULL OR p_execution_id IS NULL OR p_owner_user_id IS NULL OR p_desired_outcome_digest !~ '^[0-9a-f]{64}$' OR p_constraints_digest !~ '^[0-9a-f]{64}$' OR jsonb_typeof(p_compatibility_pins)<>'object' OR p_compatibility_pins->>'version'<>'v1' OR p_compatibility_pins->>'compatibilityMode'<>'software_engineering_legacy_v1' OR length(btrim(coalesce(v_policy,''))) NOT BETWEEN 1 AND 256 OR jsonb_typeof(p_resource_bindings)<>'array' OR length(btrim(p_workflow_revision)) NOT BETWEEN 1 AND 256 OR p_reason_code !~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$' THEN RAISE EXCEPTION 'VNext mission creation arguments are invalid' USING ERRCODE='22023'; END IF;
 INSERT INTO public.missions(id,owner_principal_type,owner_principal_id,desired_outcome_digest,constraints_digest,compatibility_pins,created_at,updated_at) VALUES(p_mission_id,'user',p_owner_user_id,p_desired_outcome_digest,p_constraints_digest,p_compatibility_pins,v_now,v_now); INSERT INTO public.executions(id,mission_id,workflow_revision,resource_bindings,created_at,updated_at) VALUES(p_execution_id,p_mission_id,p_workflow_revision,p_resource_bindings,v_now,v_now);
 IF p_task_id IS NOT NULL THEN INSERT INTO public.task_mission_bindings(task_id,mission_id,current_execution_id) VALUES(p_task_id,p_mission_id,p_execution_id); INSERT INTO public.runtime_transition_audits(entity_kind,entity_id,to_lifecycle_state,resulting_revision,actor_principal_type,actor_principal_id,reason_code,governing_policy_revision,occurred_at) VALUES('task_binding',p_task_id,'bound',0,'user',p_owner_user_id,p_reason_code,v_policy,v_now); END IF;
 INSERT INTO public.runtime_transition_audits(entity_kind,entity_id,from_lifecycle_state,to_lifecycle_state,outcome,resulting_revision,actor_principal_type,actor_principal_id,reason_code,governing_policy_revision,occurred_at) VALUES('mission',p_mission_id,NULL,'draft',NULL,0,'user',p_owner_user_id,p_reason_code,v_policy,v_now),('execution',p_execution_id,NULL,'created',NULL,0,'user',p_owner_user_id,p_reason_code,v_policy,v_now); RETURN QUERY SELECT p_mission_id,p_execution_id,v_now;
END; $$;
