CREATE FUNCTION forge.transition_vnext_mission_v1(p_mission_id uuid,p_expected_revision bigint,p_to_lifecycle_state text,p_outcome text,p_actor_user_id uuid,p_reason_code text,p_evidence_digest text DEFAULT NULL) RETURNS TABLE(resulting_revision bigint,occurred_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_from text; v_revision bigint; v_owner uuid; v_policy text; v_now timestamptz:=clock_timestamp();
BEGIN
 IF session_user<>'forge' THEN RAISE EXCEPTION 'VNext mission transition requires Forge application login' USING ERRCODE='42501'; END IF; IF p_expected_revision IS NULL OR p_expected_revision<0 OR p_to_lifecycle_state NOT IN('draft','active','waiting','paused','terminal') OR (p_to_lifecycle_state='terminal')<>(p_outcome IS NOT NULL) OR(p_outcome IS NOT NULL AND p_outcome NOT IN('succeeded','failed','cancelled')) OR p_actor_user_id IS NULL OR p_reason_code !~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$' OR(p_evidence_digest IS NOT NULL AND p_evidence_digest !~ '^[0-9a-f]{64}$') THEN RAISE EXCEPTION 'VNext mission transition arguments are invalid' USING ERRCODE='22023'; END IF;
 SELECT lifecycle_state,state_revision,owner_principal_id,compatibility_pins->>'policyRevision' INTO v_from,v_revision,v_owner,v_policy FROM public.missions WHERE id=p_mission_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'VNext mission does not exist' USING ERRCODE='P3342'; END IF; IF v_owner IS DISTINCT FROM p_actor_user_id THEN RAISE EXCEPTION 'VNext mission owner authorization failed' USING ERRCODE='P3345'; END IF; IF v_revision<>p_expected_revision THEN RAISE EXCEPTION 'VNext mission revision conflict' USING ERRCODE='P3343'; END IF; IF v_from='terminal' THEN RAISE EXCEPTION 'VNext mission terminal state is absorbing' USING ERRCODE='P3344'; END IF; IF NOT((v_from='draft' AND p_to_lifecycle_state IN('active','paused','terminal'))OR(v_from='active' AND p_to_lifecycle_state IN('waiting','paused','terminal'))OR(v_from='waiting' AND p_to_lifecycle_state IN('active','paused','terminal'))OR(v_from='paused' AND p_to_lifecycle_state IN('active','terminal'))) THEN RAISE EXCEPTION 'VNext mission lifecycle transition is invalid' USING ERRCODE='P3346'; END IF;
 UPDATE public.missions SET lifecycle_state=p_to_lifecycle_state,outcome=p_outcome,state_revision=state_revision+1,updated_at=v_now,active_at=CASE WHEN p_to_lifecycle_state='active' THEN coalesce(active_at,v_now) ELSE active_at END,waiting_at=CASE WHEN p_to_lifecycle_state='waiting' THEN coalesce(waiting_at,v_now) ELSE waiting_at END,paused_at=CASE WHEN p_to_lifecycle_state='paused' THEN coalesce(paused_at,v_now) ELSE paused_at END,terminal_at=CASE WHEN p_to_lifecycle_state='terminal' THEN v_now ELSE NULL END WHERE id=p_mission_id; INSERT INTO public.runtime_transition_audits(entity_kind,entity_id,from_lifecycle_state,to_lifecycle_state,outcome,resulting_revision,actor_principal_type,actor_principal_id,reason_code,governing_policy_revision,evidence_digest,occurred_at) VALUES('mission',p_mission_id,v_from,p_to_lifecycle_state,p_outcome,v_revision+1,'user',p_actor_user_id,p_reason_code,v_policy,p_evidence_digest,v_now); RETURN QUERY SELECT v_revision+1,v_now;
END; $$;
