CREATE FUNCTION forge.transition_vnext_execution_v1(p_execution_id uuid,p_expected_revision bigint,p_to_lifecycle_state text,p_outcome text,p_blocker_reason_code text,p_actor_user_id uuid,p_reason_code text,p_evidence_digest text DEFAULT NULL) RETURNS TABLE(resulting_revision bigint,occurred_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_from text; v_revision bigint; v_owner uuid; v_policy text; v_now timestamptz:=clock_timestamp();
BEGIN
 IF session_user<>'forge' THEN RAISE EXCEPTION 'VNext execution transition requires Forge application login' USING ERRCODE='42501'; END IF; IF p_expected_revision IS NULL OR p_expected_revision<0 OR p_to_lifecycle_state NOT IN('created','admitted','queued','leased','running','waiting','terminal') OR(p_to_lifecycle_state='terminal')<>(p_outcome IS NOT NULL) OR(p_outcome IS NOT NULL AND p_outcome NOT IN('succeeded','failed','cancelled','blocked','indeterminate')) OR p_actor_user_id IS NULL OR p_reason_code !~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$' OR(p_blocker_reason_code IS NOT NULL AND p_blocker_reason_code !~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$')OR(p_evidence_digest IS NOT NULL AND p_evidence_digest !~ '^[0-9a-f]{64}$') THEN RAISE EXCEPTION 'VNext execution transition arguments are invalid' USING ERRCODE='22023'; END IF;
 SELECT execution.lifecycle_state,execution.state_revision,mission.owner_principal_id,mission.compatibility_pins->>'policyRevision' INTO v_from,v_revision,v_owner,v_policy FROM public.executions execution JOIN public.missions mission ON mission.id=execution.mission_id WHERE execution.id=p_execution_id FOR UPDATE OF execution,mission; IF NOT FOUND THEN RAISE EXCEPTION 'VNext execution does not exist' USING ERRCODE='P3342'; END IF; IF v_owner IS DISTINCT FROM p_actor_user_id THEN RAISE EXCEPTION 'VNext execution owner authorization failed' USING ERRCODE='P3345'; END IF; IF v_revision<>p_expected_revision THEN RAISE EXCEPTION 'VNext execution revision conflict' USING ERRCODE='P3343'; END IF; IF v_from='terminal' THEN RAISE EXCEPTION 'VNext execution terminal state is absorbing' USING ERRCODE='P3344'; END IF; IF NOT((v_from='created' AND p_to_lifecycle_state IN('admitted','terminal'))OR(v_from='admitted' AND p_to_lifecycle_state IN('queued','terminal'))OR(v_from='queued' AND p_to_lifecycle_state IN('leased','terminal'))OR(v_from='leased' AND p_to_lifecycle_state IN('running','queued','terminal'))OR(v_from='running' AND p_to_lifecycle_state IN('waiting','terminal'))OR(v_from='waiting' AND p_to_lifecycle_state IN('queued','terminal'))) THEN RAISE EXCEPTION 'VNext execution lifecycle transition is invalid' USING ERRCODE='P3346'; END IF;
 UPDATE public.executions SET lifecycle_state=p_to_lifecycle_state,outcome=p_outcome,blocker_reason_code=p_blocker_reason_code,state_revision=state_revision+1,updated_at=v_now,admitted_at=CASE WHEN p_to_lifecycle_state='admitted' THEN coalesce(admitted_at,v_now) ELSE admitted_at END,queued_at=CASE WHEN p_to_lifecycle_state='queued' THEN coalesce(queued_at,v_now) ELSE queued_at END,leased_at=CASE WHEN p_to_lifecycle_state='leased' THEN coalesce(leased_at,v_now) ELSE leased_at END,running_at=CASE WHEN p_to_lifecycle_state='running' THEN coalesce(running_at,v_now) ELSE running_at END,waiting_at=CASE WHEN p_to_lifecycle_state='waiting' THEN coalesce(waiting_at,v_now) ELSE waiting_at END,terminal_at=CASE WHEN p_to_lifecycle_state='terminal' THEN v_now ELSE NULL END WHERE id=p_execution_id; INSERT INTO public.runtime_transition_audits(entity_kind,entity_id,from_lifecycle_state,to_lifecycle_state,outcome,resulting_revision,actor_principal_type,actor_principal_id,reason_code,governing_policy_revision,evidence_digest,occurred_at) VALUES('execution',p_execution_id,v_from,p_to_lifecycle_state,p_outcome,v_revision+1,'user',p_actor_user_id,p_reason_code,v_policy,p_evidence_digest,v_now); RETURN QUERY SELECT v_revision+1,v_now;
END; $$;
