CREATE FUNCTION forge.advance_task_execution_pointer_v1(p_task_id uuid,p_expected_generation bigint,p_next_execution_id uuid,p_actor_user_id uuid,p_reason_code text) RETURNS TABLE(resulting_generation bigint,occurred_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE v_mission uuid; v_generation bigint; v_owner uuid; v_policy text; v_now timestamptz:=clock_timestamp(); BEGIN IF session_user<>'forge' THEN RAISE EXCEPTION 'VNext binding transition requires Forge application login' USING ERRCODE='42501'; END IF; SELECT binding.mission_id,binding.current_execution_generation,mission.owner_principal_id,mission.compatibility_pins->>'policyRevision' INTO v_mission,v_generation,v_owner,v_policy FROM public.task_mission_bindings binding JOIN public.missions mission ON mission.id=binding.mission_id WHERE binding.task_id=p_task_id FOR UPDATE OF binding,mission; IF NOT FOUND OR v_owner IS DISTINCT FROM p_actor_user_id THEN RAISE EXCEPTION 'VNext task binding owner authorization failed' USING ERRCODE='P3345'; END IF; IF p_expected_generation IS NULL OR p_expected_generation<>v_generation THEN RAISE EXCEPTION 'VNext task pointer generation conflict' USING ERRCODE='P3343'; END IF; IF p_reason_code !~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$' OR NOT EXISTS(SELECT 1 FROM public.executions WHERE id=p_next_execution_id AND mission_id=v_mission) THEN RAISE EXCEPTION 'VNext task pointer arguments are invalid' USING ERRCODE='22023'; END IF; UPDATE public.task_mission_bindings SET current_execution_id=p_next_execution_id,current_execution_generation=current_execution_generation+1 WHERE task_id=p_task_id; INSERT INTO public.runtime_transition_audits(entity_kind,entity_id,to_lifecycle_state,resulting_revision,actor_principal_type,actor_principal_id,reason_code,governing_policy_revision,occurred_at) VALUES('task_binding',p_task_id,'pointer_advanced',v_generation+1,'user',p_actor_user_id,p_reason_code,v_policy,v_now); RETURN QUERY SELECT v_generation+1,v_now; END; $$;
